import json
import numpy as np

def analyze_all_demos():
    with open('/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/held-out-8/play/users/u022/system/state/workspace/programs/task-5997d753.json') as f:
        demos = json.load(f)

    for i, demo in enumerate(demos):
        inp = np.array(demo['input'])
        out = np.array(demo['output'])
        bg = int(np.bincount(inp.flatten(), minlength=10).argmax())

        # Get pattern color as the non-background color
        non_bg = inp[inp != bg]
        # Take most common non-background color
        counts = np.bincount(non_bg.flatten(), minlength=10)
        pattern_color = int(np.argmax(counts[len(non_bg):])) + int(len(non_bg)) if len(non_bg) > 0 else 0
        pattern_color = int(list(set(non_bg.flatten()))[0]) if len(non_bg) > 0 else -1

        # Find all rows with pattern 
        pattern_rows = set()
        for r in range(inp.shape[0]):
            for c in range(inp.shape[1]):
                if inp[r, c] == pattern_color:
                    pattern_rows.add(r)

        if not pattern_rows:
            continue

        # Sort pattern rows
        sorted_rows = sorted(pattern_rows)
        found_run = False
        run_start = None
        runs = []

        for r in sorted_rows:
            if not found_run:
                found_run = True
                run_start = r
            elif found_run and r == sorted_rows[len([x for x in sorted_rows if x == run_start])]:
                # Check if consecutive
                if r == sorted_rows[len([x for x in sorted_rows if x < r])]:
                    pass
                else:
                    # Not consecutive, end current run
                    if run_start is not None:
                        # Find where this run ends
                        try:
                            end_idx = sorted_rows.index(r) - 1
                            start_idx = sorted_rows.index(run_start)
                        except:
                            pass
            else:
                pass

        # Simpler: find contiguous runs of rows
        current_start = None
        runs = []
        for r in range(inp.shape[0]):
            if r in pattern_rows:
                if current_start is None:
                    current_start = r
            else:
                if current_start is not None:
                    runs.append((current_start, r - 1))
                    current_start = None
        if current_start is not None:
            runs.append((current_start, inp.shape[0] - 1))

        rightmost_col = max(range(inp.shape[1]))  # last col

        # Find cells changed to 1
        ones_pos = []
        for r in range(out.shape[0]):
            for c in range(out.shape[1]):
                if out[r, c] == 1 and inp[r, c] != 1:
                    ones_pos.append((r, c))

        print(f"\n=== Demo {i} ===")
        print(f"  Grid: {inp.shape}, BG: {bg}, Pattern: {pattern_color}")
        print(f"  Pattern rows: {sorted_rows}")
        print(f"  Runs: {runs}")
        print(f"  Rightmost col: {rightmost_col}")
        print(f"  Ones at: {ones_pos}")

        if ones_pos:
            min_r, max_r = min(ones_pos, key=lambda x: x[0])[0], max(ones_pos, key=lambda x: x[0])[0]
            min_c, max_c = min(ones_pos, key=lambda x: x[1])[1], max(ones_pos, key=lambda x: x[1])[1]
            print(f"  Ones span: rows {min_r}-{max_r}, cols {min_c}-{max_c}")

            # Check which runs have 1s
            for (run_start, run_end) in runs:
                has_ones = any(run_start <= r <= run_end for r, c in ones_pos)
                print(f"    Run [{run_start},{run_end}] has 1s: {has_ones}")

                # Check if 1s are at the rightmost column
                ones_in_run = [(r, c) for r, c in ones_pos if run_start <= r <= run_end]
                if ones_in_run:
                    max_c_in_run = max(c for r, c in ones_in_run)
                    print(f"      Max col in run: {max_c_in_run}, at rightmost: {max_c_in_run >= rightmost_col}")
                else:
                    print(f"      Wait, is it in run {range(run_start, run_end+1)}?")
                    for r, c in ones_pos:
                        if run_start <= r <= run_end:
                            print(f"        Found! ({r}, {c})")

analyze_all_demos()

